/*
 * win/read_or_write_disk_record.c - read_or_write_disk_record
 *
 * Original address: 0x00E19414 (module-local, no map symbol; the name is
 * the tree's)
 * Size: 160 bytes (0x00E19414 .. 0x00E194B3)
 * Generated by: Claude Opus 5.5
 *
 * Start the data transfer of the current request (WIN block +0x60) once
 * SEEK has positioned the drive.  Reached with `bsr' from WIN_$DO_IO
 * (0x00E19844) and WIN_$INT (0x00E19CB8); runs on the caller's A5 (WIN_,
 * 0xE2B89C); status in D0, always 0.  Frame: (0x8,A6) unit.
 *
 * Blocks:
 *   0x00E1941C-0x00E19434  regs = the unit's register block; req = the
 *                          current request
 *   0x00E19438-0x00E19456  DMAC channel 3 (0xFFA000 + 0xC0): MTC = 0x10,
 *                          MAR = req->pa, BAR = req->length << 10,
 *                          BTC = 0x200
 *   0x00E1945C-0x00E19484  operation (low nibble of flags byte +0x1F, read
 *                          through a second load of +0x60) 2: OCR 0x12, go
 *                          2, the longword at +0x44 counts it; otherwise
 *                          OCR 0x92, go 1, the longword at +0x40
 *   0x00E19486-0x00E19492  MFC = 0, BFC = 1, CCR = 0xC0 (start)
 *   0x00E19498-0x00E194A4  drive: sector byte -> +6, mode 9, go
 *   0x00E194A8             return status_$ok
 */

#include "win/win_internal.h"

/* The DMAC's channel 3 (`movea.l #0xffa000,A2' 0x00E19438, offsets
 * 0xC5..0xF9), a SAU2 hardware address (arch/m68k/sau2/hw.h); a host test
 * defines SAU2_DMAC_BASE as the address of a 0x100-byte array. */
#define WIN_DMAC            ((volatile uint8_t *)SAU2_DMAC_BASE)
#define WIN_DMAC_CHAN3      (3 * DN300_DMAC_CHANNEL_SIZE)
#define WIN_DMAC_OCR        M68450_REG_OCR
#define WIN_DMAC_CCR        M68450_REG_CCR
#define WIN_DMAC_MTC        M68450_REG_MTCH
#define WIN_DMAC_MAR        M68450_REG_MARH
#define WIN_DMAC_BTC        M68450_REG_BTCH
#define WIN_DMAC_BAR        M68450_REG_BARH
#define WIN_DMAC_MFC        M68450_REG_MFC
#define WIN_DMAC_BFC        M68450_REG_BFC

/* Image constants (0x00E1943E-0x00E19492) */
#define WIN_DMAC_MTC_VALUE  0x0010
#define WIN_DMAC_BTC_VALUE  0x0200
#define WIN_DMAC_OCR_OP2    0x12
#define WIN_DMAC_OCR_OTHER  0x92
#define WIN_DMAC_CCR_START  0xC0
#define WIN_MODE_TRANSFER   0x09
#define WIN_REQ_OP_2        2
#define WIN_OP2_CNT_OFFSET   0x44
#define WIN_OTHER_CNT_OFFSET 0x40

status_$t read_or_write_disk_record(uint16_t unit)
{
    volatile uint8_t *regs;             /* A0 */
    win_$request_t *req;                /* A1 */
    volatile uint8_t *ch;               /* A2 (+0xC0) */
    uint8_t go;                         /* D0 */

    /* 0x00E1941C-0x00E19434 */
    regs = WIN_UNIT_REGS(unit);
    req = (win_$request_t *)ARCH_VA_TO_PTR(WIN_CUR_REQ_VA);

    /* 0x00E19438-0x00E19456 */
    ch = WIN_DMAC + WIN_DMAC_CHAN3;
    *(volatile uint16_t *)(ch + WIN_DMAC_MTC) = WIN_DMAC_MTC_VALUE;
    *(volatile uint32_t *)(ch + WIN_DMAC_MAR) = req->pa;
    *(volatile uint32_t *)(ch + WIN_DMAC_BAR) = req->length << 10;
    *(volatile uint16_t *)(ch + WIN_DMAC_BTC) = WIN_DMAC_BTC_VALUE;

    /* 0x00E1945C-0x00E19484 */
    if ((((win_$request_t *)ARCH_VA_TO_PTR(WIN_CUR_REQ_VA))->flags & 0x0F) ==
        WIN_REQ_OP_2) {
        ch[WIN_DMAC_OCR] = WIN_DMAC_OCR_OP2;
        go = 2;
        *(uint32_t *)(WIN_DATA_BASE + WIN_OP2_CNT_OFFSET) += 1;
    } else {
        ch[WIN_DMAC_OCR] = WIN_DMAC_OCR_OTHER;
        go = 1;
        *(uint32_t *)(WIN_DATA_BASE + WIN_OTHER_CNT_OFFSET) += 1;
    }

    /* 0x00E19486-0x00E19492 */
    ch[WIN_DMAC_MFC] = 0;
    ch[WIN_DMAC_BFC] = 1;
    ch[WIN_DMAC_CCR] = WIN_DMAC_CCR_START;

    /* 0x00E19498-0x00E194A4 */
    regs[WIN_REG_STATUS] = req->sector;
    regs[WIN_REG_MODE] = WIN_MODE_TRANSFER;
    regs[WIN_REG_GO] = go;

    /* 0x00E194A8 */
    return status_$ok;
}
